namespace {unsigned checks{},failures{};void verify(bool ok,const char* name){++checks;if(!ok){++failures;std::fprintf(stderr,"SELECTION_ROUTE_FAIL %s\n",name);}}bool tap(ux::Shell& s,int id){auto r=s.chromeTargets().rect(id);return !r.empty()&&s.finger((r.x0+r.x1)/2,(r.y0+r.y1)/2,false);}void pump(ux::Shell&s,Canvas&c){s.tick();c.changes();CHECK(!s.failed());}void ready(ux::Shell&s,Canvas&c,int target=-1){int previous=-1;until([&]{pump(s,c);if(target>=0&&previous!=s.page()){previous=s.page();std::printf("SELECTION_NAV_WAIT visible=%d target=%d\n",previous,target);}return (target<0||s.page()==target)&&s.writable()&&s.inkSettled()&&!s.document()->preparing();});}std::pair<int,int> word(ux::Shell&s){auto g=s.semantics().geometry();CHECK(g&&g->available());auto matrix=g->data["transform"].toArray();for(auto value:g->data["words"].toArray()){int at=value.toArray()[0].toInt();auto quad=g->data["chars"].toArray()[at].toObject()["quad"].toArray();double x=0,y=0;for(int k=0;k<8;k+=2){x+=quad[k].toDouble()/4;y+=quad[k+1].toDouble()/4;}int px=int(matrix[0].toDouble()*x+matrix[2].toDouble()*y+matrix[4].toDouble()),py=int(matrix[1].toDouble()*x+matrix[3].toDouble()*y+matrix[5].toDouble());if(px>180&&px<1500&&py>100&&py<1950&&!ib::reader::toolbarRect().contains(px,py))return {px,py};}throw std::runtime_error("selection-route-no-word");}void ev(reader::Touch&t,unsigned short type,unsigned short code,int value,spike::Ns at){input_event e{};e.type=type;e.code=code;e.value=value;(void)t.feed(e,false,at);}reader::Touch::Tap flick(ux::Shell&s,int dx){reader::Touch t;t.testAxes({0,1619},{0,2159});t.interactionMode(s.touchMode(),s.version());t.toolbar(s.touchToolbar());ev(t,EV_ABS,ABS_MT_TRACKING_ID,7,1);ev(t,EV_ABS,ABS_MT_POSITION_X,800,1);ev(t,EV_ABS,ABS_MT_POSITION_Y,900,1);ev(t,EV_SYN,SYN_REPORT,0,1);ev(t,EV_ABS,ABS_MT_POSITION_X,800+dx/6,30000001);ev(t,EV_SYN,SYN_REPORT,0,30000001);(void)t.takeTap();ev(t,EV_ABS,ABS_MT_POSITION_X,800+dx,500000001);ev(t,EV_SYN,SYN_REPORT,0,500000001);(void)t.takeTap();ev(t,EV_ABS,ABS_MT_TRACKING_ID,-1,600000001);ev(t,EV_SYN,SYN_REPORT,0,600000001);return t.takeTap();}bool selectedTile(const Canvas&c){auto r=ib::reader::toolbarSlot(ib::reader::SlotSelect);/* the selected tool is a rounded ink tile inside the slot: sample inside it, beside the glyph */return c.pixels[std::size_t((r.y0+r.y1)/2)*1632+r.x0+24]==ib::theme::ToolSelected;}}
int main(int argc,char**argv){QCoreApplication app(argc,argv);if(argc!=5)return 64;try{using Path=std::filesystem::path;Path source=argv[1],parent=argv[2],build=argv[3],sys=argv[4];underlay::privateDirectory(parent);for(auto format:{QString("pdf"),QString("epub")}){QTemporaryDir temp(QString::fromStdString((parent/("selection-"+format.toStdString()+"-XXXXXX")).string()));CHECK(temp.isValid());temp.setAutoRemove(false);Path data=temp.path().toStdString();auto application=stage(source,data/"stage",build,sys),root=data/"library";underlay::privateDirectory(root/"inbox");std::filesystem::copy_file(source/(format=="pdf"?"fixtures/library/authored-three-pages.pdf":"fixtures/library/authored-three-chapters.epub"),root/("inbox/authored."+format.toStdString()));std::atomic<bool> stop{false};reader::syncLibrary(application,root,stop);auto books=library::documents(root);CHECK(!books.isEmpty());auto book=books[0];{ux::Shell s(application,root,true,false,false);Canvas c(s);CHECK(s.choose(0));c.ready();ready(s,c);CHECK(s.action(ux::Action::Show));c.changes();CHECK(tap(s,ib::reader::RailSelect));ready(s,c);verify(s.selectMode()&&s.state()==ux::State::Chrome&&selectedTile(c),"selection_activation_paints_selected_toolbar");auto [x,y]=word(s);{const auto g=s.semantics().geometry();const auto words=g->data["words"].toArray(),chars=g->data["chars"].toArray();const auto selected=semantic::hit(g,x,y,1);CHECK(selected);const auto at=selected->data["characterRange"].toArray()[0].toInt(),block=chars[at].toObject()["block"].toInt();QJsonArray tokens;for(int n=0;n<words.size();++n)if(chars[words[n].toArray()[0].toInt()].toObject()["block"].toInt()==block)tokens.append(n);if(tokens.size()>1){const int targetToken=selected->data["tokenRange"].toArray()[0].toInt()==tokens.last().toInt()?tokens.first().toInt():tokens.last().toInt();auto quad=chars[words[targetToken].toArray()[0].toInt()].toObject()["quad"].toArray(),m=g->data["transform"].toArray();const double px=(quad[0].toDouble()+quad[6].toDouble())/2,py=(quad[1].toDouble()+quad[7].toDouble())/2;const int ex=int(m[0].toDouble()*px+m[2].toDouble()*py+m[4].toDouble()),ey=int(m[1].toDouble()*px+m[3].toDouble()*py+m[5].toDouble());CHECK(std::hypot(ex-x,ey-y)>25);CHECK(s.selectionDrag(x,y,ex,ey,s.version()));auto range=s.semantics().selection();CHECK(range);auto bounds=g->data["blocks"].toArray()[block].toArray();verify(range->data["text"]==g->data["text"].toString().mid(bounds[0].toInt(),bounds[1].toInt()-bounds[0].toInt()),"selection_tool_drag_captures_full_touched_block");s.semantics().dismiss();ready(s,c);}}CHECK(s.reserve());CHECK(s.append({x,y,spike::Phase::Down,spike::monotonic(),true}));CHECK(s.append({x+12,y,spike::Phase::Move,spike::monotonic(),true}));CHECK(s.append({x+12,y,spike::Phase::Up,spike::monotonic(),true}));ready(s,c);verify(s.selectMode()&&!s.semantics().hasSelection(),"hardware_eraser_never_creates_text_selection_and_keeps_selection_tool");CHECK(s.finger(x,y,true));c.changes();verify(s.semantics().hasSelection(),"long_press_selects_actual_parser_word");verify(s.state()==ux::State::Chrome&&selectedTile(c),"toolbar_stays_visible_during_selection");verify(!s.chromeTargets().rect(ib::reader::RailPen).empty(),"writing_tool_targets_stay_available");if(s.state()==ux::State::Clean){CHECK(s.action(ux::Action::Show));c.changes();}auto t=flick(s,-450);verify(t.valid&&!t.drag&&t.gesture==reader::Gesture::SwipeNext,"600ms_selection_mode_flick_is_navigation");CHECK(s.gesture(t));ready(s,c);verify(s.page()==1&&!s.semantics().hasSelection()&&s.semanticVisual().count==0,"navigation_has_no_residual_selection");verify(s.selectMode()&&s.state()==ux::State::Chrome&&selectedTile(c),"active_selection_toolbar_survives_page_turn");for(int dx:{-450,450,-450,450}){auto next=flick(s,dx);CHECK(next.valid&&s.gesture(next));}ready(s,c,1);verify(s.page()==1&&!s.semantics().hasSelection(),"rapid_selection_mode_swipes_keep_navigation_order");if(s.state()==ux::State::Clean){CHECK(s.action(ux::Action::Show));c.changes();}verify(tap(s,ib::reader::RailPen),"selection_can_switch_back_to_pen");ready(s,c);verify(!s.selectMode(),"pen_choice_exits_selection_mode");{product::Services services(product::featureDirectory(root,book));auto doc=services.snapshot()["documents"].toObject()[book.id].toObject();verify(doc["strokes"].toArray().isEmpty()&&doc["notes"].toArray().isEmpty()&&doc["highlights"].toArray().isEmpty(),"selection_and_pagination_do_not_store_ink_or_notes");}if(s.toolsView().active()){CHECK(uitest::tap(s,uitest::toolsClose(s)));c.changes();}if(s.state()==ux::State::Clean){CHECK(s.action(ux::Action::Show));c.changes();}CHECK(uitest::menu(s,ux::MenuNotes));auto settle=[&]{until([&]{pump(s,c);return s.notesPanel()&&s.notesPanel()->view().ready&&s.notesPanel()->canLeave();});};settle();CHECK(uitest::notes(s,ib::notes::HubCreate));settle();CHECK(uitest::notes(s,ib::notes::NoteSelectInk));settle();verify(s.touchMode()==reader::DragMode::Ink,"notes_lasso_has_its_own_drag_owner");auto area=s.notesPanel()->view().window.area;reader::Touch::Tap lasso;lasso.valid=lasso.drag=true;lasso.mode=reader::DragMode::Ink;lasso.epoch=s.version();lasso.startX=area.x0+100;lasso.startY=area.y0+100;lasso.x=area.x0+500;lasso.y=area.y0+250;auto stale=lasso;stale.mode=reader::DragMode::Text;verify(!s.touchDrag(stale),"text_drag_cannot_cross_into_ink_lasso");verify(s.touchDrag(lasso),"ink_lasso_routes_to_notes_without_text_or_pagination");settle();verify(s.page()==1&&!s.semantics().hasSelection()&&s.notesPanel()->view().strokeCount==0,"lasso_does_not_modify_document_or_create_ink");CHECK(uitest::notes(s,ib::notes::NoteDone));until([&]{pump(s,c);return !s.notesPanel()->active()&&!s.styledInk()->status().busy;});CHECK(s.finish(5000));}if(!failures)CHECK(temp.remove());}std::printf("SELECTION_ROUTE_CHECKS checks=%u failures=%u actual_PDF_and_EPUB=true vendor=FAKE raw_input=NONE physical=NOT_RUN\n",checks,failures);return failures?1:0;}catch(const std::exception&e){std::fprintf(stderr,"SELECTION_ROUTE_ERROR %s\n",e.what());return 1;}}
